DEFAULT_SINK = "kafka://events.gulan.internal/main"
MAX_ATTEMPTS = 3

def deliver(events, target):
    return {"target": target, "count": len(events)}

def load(events):
    from sink import DEAD_LETTER
    for attempt in range(MAX_ATTEMPTS):
        try:
            return deliver(events, DEFAULT_SINK)
        except TimeoutError:
            continue
    return deliver(events, DEAD_LETTER)
